const services=[{name:'Glam',price:2200,prefix:'glam',description:'Intensidad, definición y un acabado que roba miradas. Para esos momentos en los que quieres brillar.'},{name:'Soft glam',price:2000,prefix:'softglam',description:'Piel luminosa, tonos suaves y un equilibrio perfecto. Tu belleza, con un toque de sofisticación.'},{name:'Novias',price:2500,prefix:'novia',description:'Un maquillaje pensado para acompañarte en un día inolvidable, resaltando tu esencia en cada detalle.'},{name:'Social',price:1800,prefix:'social',description:'Un look que va contigo para celebrar, compartir y sentirte especial en cualquier ocasión.'}];
const money=n=>n.toLocaleString('en-US');
const photos=services.flatMap(s=>[1,2,3].map(n=>({src:`assets/${s.prefix}${n}.webp`,service:s.name,alt:`Trabajo de maquillaje ${s.name}, fotografía ${n}, por Remsy Garcia`})));
const booking=s=>'https://wa.me/18099692405?text='+encodeURIComponent(s?`Hola, me interesa el maquillaje ${s.name} de RD$ ${money(s.price)}. Quisiera consultar disponibilidad para una fecha.`:'Hola, me gustaría agendar una cita en ARTBYGARCIA Makeup Studio. ¿Podrías indicarme la disponibilidad?');
document.querySelectorAll('.wa').forEach(a=>{a.href=booking(null);a.target='_blank';a.rel='noopener noreferrer'});
document.getElementById('service-list').innerHTML=services.map((s,i)=>`<article class="service" id="${s.prefix}"><div><div class="service-heading"><span class="service-number">0${i+1} / MAKEUP</span><h3>${s.name}</h3></div><div class="service-gallery">${photos.filter(p=>p.service===s.name).map(p=>`<button class="photo-open" data-src="${p.src}" data-group="${s.name}" aria-label="Ampliar ${p.alt}"><img src="${p.src}" alt="${p.alt}" loading="lazy"></button>`).join('')}</div><div class="gallery-hint">TOCA UNA IMAGEN PARA EXPLORAR EL LOOK </div></div><div class="service-copy"><p>${s.description}</p><div class="service-bottom"><div class="price"><small>RD$</small>${money(s.price)}</div><a class="text-link" href="${booking(s)}" target="_blank" rel="noopener noreferrer">Agendar este look </a></div></div></article>`).join('');
// Alternating editorial layout, with all three real photos preserved per service.
const feed=document.getElementById('feed');let filter='all';function renderFeed(){feed.innerHTML=photos.filter(p=>filter==='all'||p.service===filter).map(p=>`<button class="photo-open" data-src="${p.src}" data-group="feed" aria-label="Ampliar ${p.alt}"><img src="${p.src}" alt="${p.alt}" loading="lazy"><span class="feed-label">${p.service} </span></button>`).join('')};renderFeed();
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{const active=x===b;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active))});renderFeed()}));
const menu=document.getElementById('menu-toggle'),nav=document.getElementById('navigation');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Cerrar menú':'Abrir menú')});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menú')}));
const modal=document.getElementById('lightbox'),large=document.getElementById('lightbox-photo'),caption=document.getElementById('lightbox-caption');let gallery=[],index=0,returnFocus=null;function showPhoto(){const p=gallery[index];large.src=p.src;large.alt=p.alt;caption.textContent=`${p.service} — ${index+1} / ${gallery.length}`};function move(n){index=(index+n+gallery.length)%gallery.length;showPhoto()}
document.addEventListener('click',e=>{const b=e.target.closest('.photo-open');if(!b)return;returnFocus=b;gallery=b.dataset.group==='feed'?photos.filter(p=>filter==='all'||p.service===filter):photos.filter(p=>p.service===b.dataset.group);index=gallery.findIndex(p=>p.src===b.dataset.src);showPhoto();modal.showModal();document.body.classList.add('modal-open')});
document.getElementById('close-gallery').onclick=()=>modal.close();document.getElementById('prev-photo').onclick=()=>move(-1);document.getElementById('next-photo').onclick=()=>move(1);modal.addEventListener('close',()=>{document.body.classList.remove('modal-open');returnFocus?.focus()});modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});modal.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();move(1)}if(e.key==='ArrowLeft'){e.preventDefault();move(-1)}});let touchX=0,touchY=0;large.addEventListener('touchstart',e=>{touchX=e.changedTouches[0].clientX;touchY=e.changedTouches[0].clientY},{passive:true});large.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-touchX,dy=e.changedTouches[0].clientY-touchY;if(Math.abs(dx)>50&&Math.abs(dx)>Math.abs(dy))move(dx<0?1:-1)},{passive:true});document.getElementById('year').textContent=new Date().getFullYear();
